INSERT INTO `quests` (`id`, `title`, `description`, `quest_type`, `chain_id`, `chain_order`, `min_level`, `is_repeatable`, `repeat_type`, `repeat_cooldown`, `quest_group`, `quest_tier`, `time_limit`, `season`, `is_active`, `created_at`) VALUES (1,'First Catch','Catch your very first fish! Any species, any size — just get one on the line.','collection',NULL,NULL,1,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(2,'Pond Sampler','Catch 3 different species from a pond. Try different bait to find what works!','multi_species',NULL,NULL,1,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(3,'Bread Winner','Catch 5 fish using Bread Dough as bait. Koi and Bluegill love it!','collection',NULL,NULL,1,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(4,'The Big One','Land a fish weighing over 3 pounds. Try using Minnows on a Largemouth Bass!','size',NULL,NULL,1,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(5,'Worm Farmer','Gather 50 pieces of bait from gathering points around the world. Sit down and search!','collection',NULL,NULL,1,1,'none',24,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(6,'River Runner','Head to a river and catch 5 fish. Rivers unlock at Level 3. Grasshoppers are great for trout!','collection',NULL,NULL,3,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(7,'Trout Tracker','Track down both species of trout. Rainbow Trout love Grasshoppers, Brown Trout prefer Minnows.','multi_species',NULL,NULL,3,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(8,'Lake Legend','Northern Pike are ambush predators lurking in the lake. Use Minnows or Cut Bait to lure one out.','collection',NULL,NULL,5,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(9,'Carp Whisperer','Carp are stubborn bottom feeders. Use Corn Kernels to catch 3 of them from a lake.','collection',NULL,NULL,5,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(10,'Deep Sea Debut','The ocean awaits! Catch 3 fish from ocean waters. You\'ll need Shrimp or Cut Bait and a strong line.','collection',NULL,NULL,10,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(11,'Monster Hunter','Land a true monster — a fish weighing over 20 pounds. Try deep lake or ocean fish with heavy tackle.','size',NULL,NULL,10,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(12,'The Angler\'s Rod','Prove your skill by catching 10 different species across all water types. A master angler deserves a master\'s tool.','multi_species',NULL,NULL,8,0,'none',NULL,NULL,NULL,NULL,NULL,1,'2026-09-14 18:28:34'),
(17,'Weekly Angler','Catch 30 fish this week.','collection',NULL,NULL,1,1,'weekly',168,'weekly_angler',1,NULL,NULL,1,'2026-09-14 18:28:34'),
(18,'Species Sampler','Catch 5 different species this week.','multi_species',NULL,NULL,3,1,'weekly',168,'species_sampler',1,NULL,NULL,1,'2026-09-14 18:28:34'),
(19,'Deep Sea Challenge','Catch any fish from the ocean this week.','collection',NULL,NULL,10,1,'weekly',168,'deep_sea',1,NULL,NULL,1,'2026-09-14 18:28:34'),
(20,'Heavy Hauler','Catch 10 fish weighing over 3 lbs this week.','size',NULL,NULL,5,1,'weekly',168,'heavy_hauler',1,NULL,NULL,1,'2026-09-14 18:28:34'),
(21,'Daily Catch','Catch 5 fish today. Any species, any water.','collection',NULL,NULL,1,1,'daily',24,'daily_catch',1,NULL,NULL,1,'2026-09-14 18:28:34'),
(22,'Daily Catch II','Catch 8 fish today, at least 2 from a river.','collection',NULL,NULL,3,1,'daily',24,'daily_catch',2,NULL,NULL,1,'2026-09-14 18:28:34'),
(23,'Daily Catch III','Catch 10 fish today, at least 3 from a lake.','collection',NULL,NULL,5,1,'daily',24,'daily_catch',3,NULL,NULL,1,'2026-09-14 18:28:34'),
(24,'Daily Catch IV','Catch 12 fish today, at least 3 uncommon or better.','collection',NULL,NULL,8,1,'daily',24,'daily_catch',4,NULL,NULL,1,'2026-09-14 18:28:34'),
(25,'Daily Catch V','Catch 15 fish today, at least 2 from the ocean.','collection',NULL,NULL,10,1,'daily',24,'daily_catch',5,NULL,NULL,1,'2026-09-14 18:28:34'),
(26,'Big Fish Day','Catch a fish weighing over 2 lbs.','size',NULL,NULL,1,1,'daily',24,'big_fish',1,NULL,NULL,1,'2026-09-14 18:28:34'),
(27,'Bigger Fish Day','Catch a fish weighing over 4 lbs.','size',NULL,NULL,3,1,'daily',24,'big_fish',2,NULL,NULL,1,'2026-09-14 18:28:34'),
(28,'Huge Fish Day','Catch a fish weighing over 6 lbs.','size',NULL,NULL,5,1,'daily',24,'big_fish',3,NULL,NULL,1,'2026-09-14 18:28:34'),
(29,'Massive Fish Day','Catch a fish weighing over 10 lbs.','size',NULL,NULL,8,1,'daily',24,'big_fish',4,NULL,NULL,1,'2026-09-14 18:28:34'),
(30,'Legendary Fish Day','Catch a fish weighing over 15 lbs.','size',NULL,NULL,10,1,'daily',24,'big_fish',5,NULL,NULL,1,'2026-09-14 18:28:34'),
(31,'Rare Haul','Catch 3 rare or better fish today.','rare_catch',NULL,NULL,4,1,'daily',24,'rare_haul',1,NULL,NULL,1,'2026-09-14 18:28:34'),
